    INSERT INTO src.wards (ward_id, ward_code, ward_name, ward_type, hospital, status, acuity_level, bed_count, opened_date, last_modified) SELECT ward_id, ward_code, ward_name, ward_type, hospital, status, acuity_level, bed_count, opened_date, last_modified FROM src.stage_wards WHERE release_day = @day;
    INSERT INTO src.admissions (admission_id, ward_id, admission_type, priority, status, admit_ts, discharge_ts, episode_cost_aud, nursing_hours, description, last_modified) SELECT admission_id, ward_id, admission_type, priority, status, admit_ts, discharge_ts, episode_cost_aud, nursing_hours, description, last_modified FROM src.stage_admissions WHERE release_day = @day;
