/* Coastal Health Network (Healthcare) - source database seed for the pipeline Copy demo
   Plays the role of: Patient Administration System (on-prem SQL Server)
   Run this whole script ONCE in a Fabric SQL database (or Azure SQL / SQL Server). Then release the days in order:
       EXEC src.usp_release_day 1;   -- before the first pipeline run
       EXEC src.usp_release_day 2;   -- before the second run
       EXEC src.usp_release_day 3;   -- before the third run (adds a new column = schema drift)
   Generated by tools/build_kit.py - all data is fictional. */
IF SCHEMA_ID('src') IS NULL EXEC('CREATE SCHEMA src');
GO
DROP TABLE IF EXISTS src.wards; DROP TABLE IF EXISTS src.admissions; DROP TABLE IF EXISTS src.stage_wards; DROP TABLE IF EXISTS src.stage_admissions;
CREATE TABLE src.wards (ward_id INT NOT NULL, ward_code NVARCHAR(30), ward_name NVARCHAR(100), ward_type NVARCHAR(30), hospital NVARCHAR(40), status NVARCHAR(30), acuity_level INT, bed_count DECIMAL(12,1), opened_date DATE, last_modified DATETIME2(0), CONSTRAINT pk_wards PRIMARY KEY (ward_id));
CREATE TABLE src.admissions (admission_id INT NOT NULL, ward_id INT, admission_type NVARCHAR(30), priority INT, status NVARCHAR(30), admit_ts DATETIME2(0), discharge_ts DATETIME2(0), episode_cost_aud DECIMAL(12,2), nursing_hours DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0), CONSTRAINT pk_admissions PRIMARY KEY (admission_id));
CREATE TABLE src.stage_wards (release_day INT NOT NULL, ward_id INT, ward_code NVARCHAR(30), ward_name NVARCHAR(100), ward_type NVARCHAR(30), hospital NVARCHAR(40), status NVARCHAR(30), acuity_level INT, bed_count DECIMAL(12,1), opened_date DATE, last_modified DATETIME2(0), nurse_unit_manager NVARCHAR(50));
CREATE TABLE src.stage_admissions (release_day INT NOT NULL, admission_id INT, ward_id INT, admission_type NVARCHAR(30), priority INT, status NVARCHAR(30), admit_ts DATETIME2(0), discharge_ts DATETIME2(0), episode_cost_aud DECIMAL(12,2), nursing_hours DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0));
GO
GO
CREATE OR ALTER PROCEDURE src.usp_release_day @day INT
AS
BEGIN
    SET NOCOUNT ON;
    IF @day >= 3 AND COL_LENGTH('src.wards', 'nurse_unit_manager') IS NULL
        EXEC('ALTER TABLE src.wards ADD nurse_unit_manager NVARCHAR(50) NULL');
    DELETE t FROM src.wards t WHERE EXISTS (SELECT 1 FROM src.stage_wards s WHERE s.release_day = @day AND s.ward_id = t.ward_id);
    IF @day >= 3
        EXEC('UPDATE t SET t.nurse_unit_manager = s.nurse_unit_manager FROM src.wards t JOIN src.stage_wards s ON s.ward_id = t.ward_id AND s.release_day = 3');
    DELETE t FROM src.admissions t WHERE EXISTS (SELECT 1 FROM src.stage_admissions s WHERE s.release_day = @day AND s.admission_id = t.admission_id);
    SELECT @day AS released_day, (SELECT COUNT(*) FROM src.wards) AS wards, (SELECT COUNT(*) FROM src.admissions) AS admissions;
END;
GO
